class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def findMirror(root, target):
    def dfs(node, target, is_mirror=False):
        if not node:
            return -1
        if node.val == target:
            return -1 if is_mirror else find_mirror_node(root, target)
        left_result = dfs(node.left, target, is_mirror)
        if left_result != -1:
            return left_result
        return dfs(node.right, target, not is_mirror)

    def find_mirror_node(node, target):
        if not node:
            return -1
        if node.val != target:
            left_result = find_mirror_node(node.left, target)
            if left_result != -1:
                return find_mirror_node(node.right, left_result)
            right_result = find_mirror_node(node.right, target)
            if right_result != -1:
                return find_mirror_node(node.left, right_result)
        return node.val

    return dfs(root, target)
